import{_ as a,c as r,o as t,b0 as i}from"./chunks/framework.BpbtKNwe.js";const l="/aillm-docs/assets/image-20251105075636349.CCihe9B0.png",o="/aillm-docs/assets/image-20251105080323367.hcMFu-j4.png",n="/aillm-docs/assets/image-20251109193724121.BYR6D5_m.png",s="/aillm-docs/assets/image-20240824221803596.BUOy9Mqx.png",c="/aillm-docs/assets/image-20240824221803597.wU7KIiw4.png",p="/aillm-docs/assets/image-20251103230034835.yp9oRfa3.png",d="/aillm-docs/assets/image-20251103230052804.D7PrmjBj.png",h="/aillm-docs/assets/image-20251109202757415.BWi5aMOj.png",P="/aillm-docs/assets/image-20240825153309065._2T3APAA.png",u="/aillm-docs/assets/image-20240825153812173.CHiXRfIM.png",m="/aillm-docs/assets/982749d6e28a06637c8d2ebf10ce2a30.DidLSbMG.jpeg",I=JSON.parse('{"title":"LV005-GPU简介","description":null,"frontmatter":{"title":"LV005-GPU简介","date":"2025-11-10T21:59:20.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/cuda/cuda-basic/126b143b10f0283806a263fe","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-10T21:59:20.643Z","fulluuid":"806a263feeff43e1b19217c5241fcd8e","useduuid":"806a263fe"}},"headers":[],"relativePath":"sdoc/cuda/cuda-basic/126b143b10f0283806a263fe.md","filePath":"sdoc/10-CUDA编程/05-CUDA基础/LV005-GPU简介.md","lastUpdated":1767430713000}'),g={name:"sdoc/cuda/cuda-basic/126b143b10f0283806a263fe.md"};function U(C,e,b,f,_,G){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="lv005-gpu简介" tabindex="-1">LV005-GPU简介 <a class="header-anchor" href="#lv005-gpu简介" aria-label="Permalink to &quot;LV005-GPU简介&quot;">​</a></h1><p>这节我们来看看什么是 GPU。</p><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>随着大模型产业的发展，AI 训练 &amp; 推理对算力的需求越来越大，AI 的计算也越来越离不开 GPU 的支持。</p><p>目前，用于 AI 计算的芯片可以分为：</p><ul><li>CPU（通用处理器）；</li><li>GPU（通用图形处理器）；</li><li>NPU / TPU（AI 专用处理器）。</li></ul><h2 id="二、并行的概念" tabindex="-1">二、并行的概念 <a class="header-anchor" href="#二、并行的概念" aria-label="Permalink to &quot;二、并行的概念&quot;">​</a></h2><table><tbody><tr><td align="left"> 串行(Sequential/Serial)<br>一个处理器按顺序处理每一个任务 </td><td align="center"><img src="'+l+'" width="63%"></td></tr><tr><td align="left"> 并发(Concurrent)<br>指一个处理器同时处理多个任务。</td><td align="center"><img src="'+o+'" alt="image-20251105080323367" width="63%"></td></tr><tr><td align="left"> 并行(Parallel)<br>多个处理器或者是多核的处理器同时处理多个不同的任务。</td><td align="center"><img src="'+n+'" width="63%"></td></tr></tbody></table><ul><li>串行（Serial）：就是只有一个处理器，每次只处理一个任务，这个任务处理完了才能处理下一个任务。</li><li>并发(concurrency)：指在同一时刻只能有一条指令执行，但多个进程指令被快速的轮换执行，使得在宏观上具有多个进程同时执行的效果，但在微观上并不是同时执行的，只是把时间分成若干段，使多个进程快速交替的执行。当有多个线程在操作时, 如果系统只有一个 CPU, 则它根本不可能真正同时进行一个以上的线程, 它只能把 CPU 运行时间划分成若干个时间段, 再将时间段分配给各个线程执行, 在一个时间段的线程代码运行时, 其它线程处于挂起状态.</li><li>并行(parallel)：指在同一时刻，有多条指令在多个处理器上同时执行。</li></ul><h2 id="三、cpu-与-gpu" tabindex="-1">三、CPU 与 GPU <a class="header-anchor" href="#三、cpu-与-gpu" aria-label="Permalink to &quot;三、CPU 与 GPU&quot;">​</a></h2><h3 id="_1-cpu" tabindex="-1">1. CPU <a class="header-anchor" href="#_1-cpu" aria-label="Permalink to &quot;1. CPU&quot;">​</a></h3><p>CPU：叫做中央处理器（central processing unit）作为计算机系统的运算和控制核心，是信息处理、程序运行的最终执行单元。中央处理器 (CPU) 由数十亿个晶体管构成，可以拥有多个处理核心，通常被称为计算机的“大脑”。</p><img src="'+s+'" alt="image-20240824221803596" style="zoom:50%;"><p>可以形象的理解为有 25%的 ALU(运算单元)、有 25%的 Control(控制单元)、50%的 Cache(缓存单元)。</p><h3 id="_2-gpu" tabindex="-1">2. GPU <a class="header-anchor" href="#_2-gpu" aria-label="Permalink to &quot;2. GPU&quot;">​</a></h3><p>GPU：叫做图形处理器。图形处理器（英语：Graphics Processing Unit，缩写：GPU），又称显示核心、视觉处理器、显示芯片，是一种专门在个人电脑、工作站、游戏机和一些移动设备（如平板电脑、智能手机等）上做图像和图形相关运算工作的微处理器。</p><p>图形处理单元 (GPU) 具有许多更小、更专业的核心。这些核心协同运行，并将处理任务同时（即并行）划分给许多核心，从而提供强劲的性能。GPU 擅长处理高度并行任务，例如在游戏过程中渲染视觉效果，在内容创作过程中操纵视频数据，以及在密集型 AI 工作负载中计算结果。</p><img src="'+c+'" alt="image-20240824221803597" style="zoom:50%;"><p>可以形象的理解为 90%的 ALU(运算单元)，5%的 Control(控制单元)、5%的 Cache(缓存单元)。</p><h3 id="_3-有什么区别" tabindex="-1">3. 有什么区别 <a class="header-anchor" href="#_3-有什么区别" aria-label="Permalink to &quot;3. 有什么区别&quot;">​</a></h3><p>从硬件设计上来看，GPU 的 DRAM 时延（数据搬运、指令执行的延迟）远高于 CPU，但 GPU 的线程数远高于 CPU（有非常多的线程，为大量大规模任务并行而去设计的）。</p><ul><li>CPU：降低延迟、并发（Concurrency，能够处理多个任务的功能，但不一定是同时），可能更希望在一个线程里完成所有的工作（串行，优化线程的执行速率和效率）；</li><li>GPU：最大化吞吐量、并行度（Parallelism，同时可以执行多少任务）。利用多线程对循环进行展开，来提高硬件整体的利用率。</li></ul><h3 id="_4-总结" tabindex="-1">4. 总结 <a class="header-anchor" href="#_4-总结" aria-label="Permalink to &quot;4. 总结&quot;">​</a></h3><table><tbody><tr><td align="center"> CPU(Central Processing Unit)</td><td align="center"> GPU(Graphics Processing Unit)</td></tr><tr><td align="left"> ■ “全能战士”<br>■ 通用和复杂计算/逻辑处理、控制流…<br>■ 少量复杂核心、复杂控制单元、低延迟…</td><td align="left"> ■ “流水线工人”<br>■ 相对简单的大量数据并行<br>■ 大量简化核心、极简控制单元、高吞吐…</td></tr><tr><td width="50%" align="center"><img src="'+p+'"> <br>Intel Core i7 </td><td width="50%" align="center"><img src="'+d+'"> <br> NVIDIA A100 </td></tr></tbody></table> 硬件设计上有根本区别，GPU 专为大规模数据并行设计，在这些任务下“三个臭皮匠顶个诸葛亮” <h2 id="四、cuda-简介" tabindex="-1">四、CUDA 简介 <a class="header-anchor" href="#四、cuda-简介" aria-label="Permalink to &quot;四、CUDA 简介&quot;">​</a></h2><h3 id="_1-cuda-是什么" tabindex="-1">1. CUDA 是什么？ <a class="header-anchor" href="#_1-cuda-是什么" aria-label="Permalink to &quot;1. CUDA 是什么？&quot;">​</a></h3><p>CUDA（Compute Unified Device Architecture）是由 NVIDIA 开发的一个并行计算平台和编程模型。它允许软件开发人员和研究人员利用 NVIDIA 的 GPU（图形处理单元）进行高性能计算。CUDA 提供了一系列 API 和工具，使得开发者能够编写和优化在 GPU 上运行的计算密集型任务。</p><h3 id="_2-发展历史" tabindex="-1">2. 发展历史 <a class="header-anchor" href="#_2-发展历史" aria-label="Permalink to &quot;2. 发展历史&quot;">​</a></h3><p>GPU 最初的使命是加速图形渲染。而渲染一帧图像，本质上就是对数百万个像素点进行相似的计算，这天然就是一种大规模并行任务。</p><p>2001 年，NVIDIA 发布 GeForce 3，首次引入 <strong>可编程着色器 (Programmable Shaders)。</strong> 实质上允许开发者为 GPU 编写软件，让 GPU 的 <strong>众多并行处理单元</strong> 去同时执行，以精确控制光照和颜色如何加载到显示器上。这是朝着加速计算方向迈出的重要一步，因为它允许开发者直接为 GPU 编写软件。</p><p>一批敏锐的研究人员意识到，GPU 的本质就是一个拥有数百甚至数千个核心的大规模并行架构，其浮点运算吞吐量远超当时的 CPU。他们的核心想法是：<strong>能不能用 GPU 进行科学计算？</strong> 开始探索利用 GPU 计算科学计算问题，从而利用 GPU 的算力。这便是 GPGPU（通用计算 GPU）的萌芽。但是门槛非常高， 需要开发者同时精通图形学和科学计算。</p><p>NVIDIA敏锐地捕捉到了GPGPU的发展潜力，开始不再局限于加速图形渲染，主动拥抱GPGPU。2006年，发布了第一款为通用计算设计的统一架构GPU - <strong>GeForce 8800 GTX</strong> 显卡（G80架构）。它将GPU内部的计算单元统一起来，形成了<strong>一个庞大的、灵活的并行核心阵列</strong>，为通用计算铺平了硬件道路。</p><p>2007年，NVIDIA正式推出了CUDA平台。<strong>CUDA 的革命性在于，它提供了一套简单的编程模型，让开发者能用近似 C 语言的方式，轻松地驾驭 GPU 内部成百上千个并行核心。</strong> 开发者无需再关心复杂的图形接口，可以直接编写在数千个线程上并发执行的程序。至此终结了 GPGPU 编程的蛮荒时代，让 GPU 计算真正走下神坛，成为开发者触手可及的强大工具。</p><h2 id="五、gpu-的架构" tabindex="-1">五、GPU 的架构 <a class="header-anchor" href="#五、gpu-的架构" aria-label="Permalink to &quot;五、GPU 的架构&quot;">​</a></h2><p>我们这部分参考：<a href="https://images.nvidia.cn/aem-dam/en-zz/Solutions/data-center/nvidia-ampere-architecture-whitepaper.pdf" target="_blank" rel="noreferrer">nvidia-ampere-architecture-whitepaper.pdf</a></p><h3 id="_1-gpu-的硬件单元" tabindex="-1">1. GPU 的硬件单元 <a class="header-anchor" href="#_1-gpu-的硬件单元" aria-label="Permalink to &quot;1. GPU 的硬件单元&quot;">​</a></h3><p>打开 <a href="https://images.nvidia.cn/aem-dam/en-zz/Solutions/data-center/nvidia-ampere-architecture-whitepaper.pdf" target="_blank" rel="noreferrer">nvidia-ampere-architecture-whitepaper.pdf</a> 的第 20 和 22 页，有如下两张图：</p><p><img src="'+h+'" alt="image-20251109202757415"></p><p>从这里，我们可以知道，在 GPU 的硬件架构中，包含以下单元：</p><ul><li>GPC：Graph Possessed Cluster，图像处理簇。GPC 负责处理图形渲染和计算任务。每个 GPC 包含多个 TPC，以及与其相关的专用硬件单元和缓存。</li><li>TPC：Texture Possessed Cluster，纹理处理簇。TPC 负责执行纹理采样和滤波操作，以从纹理数据中获取采样值，并应用于图形渲染中的相应像素。</li><li>SM：Stream Multiprocessors，流式多处理器。SM 是是 GPU 的主要计算单元，负责执行并行计算任务。每个 SM 都包含多个流多处理器（CUDA Core/Tensor Core/RT Core 等 ），可以同时执行多个线程块中的指令。SM 通过分配线程、调度指令和管理内存等操作，实现高效的并行计算。</li><li>HBM：High Band Memory，高带宽处理器。</li></ul><p>一个 GPC 包含多个 TPC，一个 TPC 包含多个 SM，一个 SM 包含多个 Block、Thread 以及各种 CUDA Tensor Core。</p><h4 id="_1-1-sm" tabindex="-1">1.1 SM <a class="header-anchor" href="#_1-1-sm" aria-label="Permalink to &quot;1.1 SM&quot;">​</a></h4><p>SM（流式多处理器）的核心组件包括：CUDA 核心、共享内存、寄存器等，它包含许多为线程执行数学运算的 Core，是 NVIDIA 的核心，每一个 SM 都可以并发地执行数百个线程。具体地，SM 包括以下单元：</p><ul><li>CUDA Core：向量运行单元（FP32-FPU、FP64-DPU、INT32-ALU）；包含了一个整数运算单元 ALU (Integer Arithmetic Logic Unit) 和一个浮点运算单元 FPU (Floating Point Unit) 。后来称为SP，SP就是CUDA Core的前身。</li><li>Tensor Core：张量运算单元（FP16、BF16、INT8、INT4，专门针对 AI 的矩阵计算）；Tensor Core 之所以计算效率高是因为硬件层面实现了 4x4x4 的矩阵乘法运算。</li><li>Special Function Units：特殊函数单元，SFU，超越函数和数学函数；</li><li>warp Scheduler：线程束调度器；</li><li>Dispatch Unit：指令分发单元；</li><li>Multi Level Cache：多级缓存（L0/L1 Instruction Cache、L1 Data Cache &amp; Shared Memory）；</li><li>Register File：寄存器堆；</li><li>Load/Store：访问存储单元（LD/ST，负责处理数据）。</li></ul><blockquote><p>后来，CUDA Core 演变为了单独的 FP32、FPU、INT32-ALU。</p></blockquote><h4 id="_1-2-tensor-core" tabindex="-1">1.2 Tensor Core <a class="header-anchor" href="#_1-2-tensor-core" aria-label="Permalink to &quot;1.2 Tensor Core&quot;">​</a></h4><p>Tensor Core 可以支持混合精度运算。混合精度是指在底层硬件算子（Tensor Core）层面，使用半精度（FP16）作为输入和输出，使用全精度（FP32）进行中间结果计算从而不损失过多精度的技术。</p><p><img src="'+P+'" alt="image-20240825153309065"></p><p>每个 Tensor Core 每周期能执行 <code>4*4*4</code> GEMM，即 64 个 FMA。</p><p><img src="'+u+'" alt="image-20240825153812173"></p><p>Tensor Core 可以通过 Warp 把多个线程聚合起来一起进行计算和控制。最终对外提供一个 <code>16*16*16</code> 的 API 给到 CUDA。</p><h3 id="_2-与cpu的交互" tabindex="-1">2. 与CPU的交互 <a class="header-anchor" href="#_2-与cpu的交互" aria-label="Permalink to &quot;2. 与CPU的交互&quot;">​</a></h3><p>CPU是整个系统的核心，是总指挥，GPU的任务指令是由CPU分配的。CPU通过PCIe总线给GPU发送指令和数据交互。而PCIe支持DMA和MMIO两种通讯模式：</p><ul><li>MMIO（内存映射I/O）由CPU直接控制数据读写，操作系统会把设备地址映射到CPU的虚拟空间中，适合小数据量的指令交互</li><li>DMA（直接内存访问）则允许设备绕过CPU直接访问系统内存，专为大数据块的高效传输设计。</li></ul><p>CPU通过IMC和Memory Channel访问内存，为了提升数据传输带宽，高端CPU通常会支持多内存通道，即多IMC和Memory Channel的组合，以满足日益增长的数据处理需求。</p><p><img src="'+m+'" alt="img"></p><blockquote><p>参考资料：</p><p><a href="https://www.nvidia.com/content/PDF/nvidia-ampere-ga-102-gpu-architecture-whitepaper-v2.1.pdf" target="_blank" rel="noreferrer">nvidia-ampere-ga-102-gpu-architecture-whitepaper-v2.1.pdf</a></p><p><a href="https://images.nvidia.cn/aem-dam/en-zz/Solutions/data-center/nvidia-ampere-architecture-whitepaper.pdf" target="_blank" rel="noreferrer">nvidia-ampere-architecture-whitepaper.pdf</a></p><p><a href="https://docs.nvidia.com/cuda/cuda-c-programming-guide/index.html" target="_blank" rel="noreferrer">CUDA C++ Programming Guide — CUDA C++ Programming Guide</a></p><p><a href="https://docs.nvidia.com/deeplearning/performance/dl-performance-gpu-background/" target="_blank" rel="noreferrer">GPU Performance Background User&#39;s Guide - NVIDIA Docs</a></p><p><a href="https://shen-shanshan.github.io/articles/nvidia-gpu-%E7%A1%AC%E4%BB%B6%E6%9E%B6%E6%9E%84%E5%85%A5%E9%97%A8" target="_blank" rel="noreferrer">NVIDIA GPU 硬件架构入门 · Home</a></p><p><a href="https://ieeexplore.ieee.org/document/9623445" target="_blank" rel="noreferrer">Evolution of the Graphics Processing Unit (GPU) | IEEE Journals &amp; Magazine | IEEE Xplore</a></p><p><a href="https://cloud.tencent.com/developer/article/2538756" target="_blank" rel="noreferrer">每个程序员都应该了解的 GPU 工作原理：从硬件到架构-腾讯云开发者社区-腾讯云</a></p><p><a href="https://blog.csdn.net/2301_81940605/article/details/153251261" target="_blank" rel="noreferrer">每个程序员都应该了解的GPU工作原理：从硬件到架构，大模型入门到精通，收藏这篇就足够了！_gpu架构与编程 赵地-CSDN博客</a></p></blockquote>',58)])])}const D=a(g,[["render",U]]);export{I as __pageData,D as default};
